// Save creates the NubanDeposit entities in the database.
func (ndcb *NubanDepositCreateBulk) Save(ctx context.Context) ([]*NubanDeposit, error) {
	if ndcb.err != nil {
		return nil, ndcb.err
	}
	specs := make([]*sqlgraph.CreateSpec, len(ndcb.builders))
	nodes := make([]*NubanDeposit, len(ndcb.builders))
	mutators := make([]Mutator, len(ndcb.builders))
	for i := range ndcb.builders {
		func(i int, root context.Context) {
			builder := ndcb.builders[i]
			builder.defaults()
			var mut Mutator = MutateFunc(func(ctx context.Context, m Mutation) (Value, error) {
				mutation, ok := m.(*NubanDepositMutation)
				if !ok {
					return nil, fmt.Errorf("unexpected mutation type %T", m)
				}
				if err := builder.check(); err != nil {
					return nil, err
				}
				builder.mutation = mutation
				var err error
				nodes[i], specs[i] = builder.createSpec()
				if i < len(mutators)-1 {
					_, err = mutators[i+1].Mutate(root, ndcb.builders[i+1].mutation)
				} else {
					spec := &sqlgraph.BatchCreateSpec{Nodes: specs}
					spec.OnConflict = ndcb.conflict
					// Invoke the actual operation on the latest mutation in the chain.
					if err = sqlgraph.BatchCreate(ctx, ndcb.driver, spec); err != nil {
						if sqlgraph.IsConstraintError(err) {
							err = &ConstraintError{msg: err.Error(), wrap: err}
						}
					}
				}
				if err != nil {
					return nil, err
				}
				mutation.id = &nodes[i].ID
				mutation.done = true
				return nodes[i], nil
			})
			for i := len(builder.hooks) - 1; i >= 0; i-- {
				mut = builder.hooks[i](mut)
			}
			mutators[i] = mut
		}(i, ctx)
	}
	if len(mutators) > 0 {
		if _, err := mutators[0].Mutate(ctx, ndcb.builders[0].mutation); err != nil {
			return nil, err
		}
	}
	return nodes, nil
}

